            // re-render often, and this runs after every DOM change)
            if (n.__eqilT === t && n.__eqilL === L) { continue; }
            n.__eqilT = t; n.__eqilL = L;
            var cur = squash(t), out = null, i;
            if (Object.prototype.hasOwnProperty.call(M.exact, "~" + cur)) { out = M.exact["~" + cur]; }
            else {
                var s = cur;
