            description: 'The demand curve is <strong>P = 200 - 2Q</strong> and the market price is <strong>$80</strong>.<br><br>Calculate the <strong>consumer surplus</strong>. (Hint: find the equilibrium quantity first, then integrate.)',
            descriptionEs: 'La curva de demanda es <strong>P = 200 - 2Q</strong> y el precio de mercado es <strong>$80</strong>.<br><br>Calcula el <strong>excedente del consumidor</strong>. (Pista: encuentra la cantidad de equilibrio primero, luego integra.)',
            formula: 'CS = integral from 0 to Q* of (Demand(Q) - P*) dQ, where Q* is equilibrium quantity',
            formulaEs: 'CS = integral de 0 a Q* de (Demanda(Q) - P*) dQ, donde Q* es la cantidad de equilibrio',
            answer: 3600,
            maxPoints: 13,
            unit: '$',
            hint: 'At P = 80: Q* = (200 - 80) / 2 = 60. Then integrate (120 - 2Q) from 0 to 60.',
            hintEs: 'A P = 80: Q* = (200 - 80) / 2 = 60. Luego integra (120 - 2Q) de 0 a 60.'
        }
    ];

    function eqLang() {
        try { return (window.mySimulation && window.mySimulation.lang) || 'en'; } catch (e) { return 'en'; }
    }

    class MathBizAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'MathBiz: Business Mathematics Lab';
            this.version = '1.0.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    maxPossible: 100,
                    correctCount: 0,
                    answeredCount: 0,
                    partialCount: 0,
                    streak: 0,
                    bestStreak: 0,
                    scoreHistory: [],
                    errorHistory: [],
                    pointsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    answer: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, PROBLEMS.length - 1);
            var problem = PROBLEMS[idx];
            var isEs = eqLang() === 'es';

            var badge = document.getElementById('topicBadge');
            if (badge) badge.textContent = isEs ? problem.topicEs : problem.topic;

            var titleEl = document.getElementById('problemTitle');
            if (titleEl) titleEl.textContent = isEs ? problem.titleEs : problem.title;

            var descEl = document.getElementById('problemDescription');
            if (descEl) descEl.innerHTML = isEs ? problem.descriptionEs : problem.description;

            var formulaEl = document.getElementById('formulaBox');
            if (formulaEl) formulaEl.textContent = (isEs && problem.formulaEs) ? problem.formulaEs : problem.formula;

            var unitEl = document.getElementById('unitLabel');
            if (unitEl) unitEl.textContent = problem.unit === '$' ? '$' : '';

            var answerInput = document.getElementById('answerInput');
            if (answerInput) answerInput.value = '';

            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';
        }

        validateDecisions(decisions) {
            var input = document.getElementById('answerInput');
            if (input) decisions.answer = parseFloat(input.value);

            if (isNaN(decisions.answer)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('answer_required'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min(state.currentPeriod - 1, PROBLEMS.length - 1);
            var problem = PROBLEMS[idx];
            var isEs = eqLang() === 'es';
            var localHint = isEs ? problem.hintEs : problem.hint;

            var correct = problem.answer;
            var submitted = d.answer;
            var errorPct = Math.abs(submitted - correct) / Math.abs(correct) * 100;
            var points = 0;
            var grade = 'incorrect';

            if (errorPct <= 2) {
                points = problem.maxPoints;
                grade = 'correct';
                ds.correctCount += 1;
                ds.streak += 1;
            } else if (errorPct <= 5) {
                points = Math.round(problem.maxPoints * 0.7);
                grade = 'partial';
                ds.partialCount += 1;
                ds.streak = 0;
            } else if (errorPct <= 15) {
                points = Math.round(problem.maxPoints * 0.3);
                grade = 'partial';
                ds.partialCount += 1;
                ds.streak = 0;
            } else {
                points = 0;
                grade = 'incorrect';
                ds.streak = 0;
            }

            if (ds.streak > ds.bestStreak) ds.bestStreak = ds.streak;

            ds.answeredCount = (ds.answeredCount || 0) + 1;
            ds.score += points;
            ds.scoreHistory.push(ds.score);
            ds.errorHistory.push(Math.round(errorPct * 100) / 100);
            ds.pointsHistory.push(points);

            // overallScore is the running percent of points earned versus points possible in the problems seen so far, matching the percentage getPerformanceSummary reports at completion
            var maxSoFar = 0;
            for (var mi = 0; mi <= idx; mi++) { maxSoFar += PROBLEMS[mi].maxPoints; }
            var overallScore = maxSoFar > 0 ? Math.round(100 * ds.score / maxSoFar) : 0;
            overallScore = Math.max(0, Math.min(100, overallScore));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackTitle = document.getElementById('feedbackTitle');
            var feedbackText = document.getElementById('feedbackText');
            var feedbackDetail = document.getElementById('feedbackDetail');

            if (feedbackPanel) {
                feedbackPanel.style.display = 'block';
                feedbackPanel.className = 'mathbiz-sim-feedback mathbiz-sim-feedback-' + grade;

                if (grade === 'correct') {
                    if (feedbackTitle) feedbackTitle.textContent = '\u2705 ' + window.mySimulation.t('feedback_correct');
                    if (feedbackText) feedbackText.textContent = window.mySimulation.t('feedback_perfect');
                } else if (grade === 'partial') {
                    if (feedbackTitle) feedbackTitle.textContent = '\u26a0\ufe0f ' + window.mySimulation.t('feedback_partial');
                    if (feedbackText) feedbackText.innerHTML = window.mySimulation.t('feedback_close') + '<br>' + localHint;
                } else {
                    if (feedbackTitle) feedbackTitle.textContent = '\u274c ' + window.mySimulation.t('feedback_incorrect');
                    if (feedbackText) feedbackText.innerHTML = window.mySimulation.t('feedback_review') + '<br>' + localHint;
                }

                if (feedbackDetail) {
                    var detailText = window.mySimulation.t('feedback_your_answer') + ': ';
                    if (problem.unit === '$') detailText += '$' + submitted.toLocaleString();
                    else detailText += submitted.toLocaleString() + ' ' + problem.unit;
                    detailText += ' | ' + window.mySimulation.t('feedback_correct_answer') + ': ';
                    if (problem.unit === '$') detailText += '$' + correct.toLocaleString();
                    else detailText += correct.toLocaleString() + ' ' + problem.unit;
                    detailText += ' | ' + window.mySimulation.t('feedback_points') + ': ' + points + '/' + problem.maxPoints;
                    feedbackDetail.textContent = detailText;
                }
            }

            var isLast = state.currentPeriod >= PROBLEMS.length; var submitBtn = document.getElementById('nextPeriodBtn'); var nextBtn = document.getElementById('nextProblemBtn'); var ansInput = document.getElementById('answerInput'); if (nextBtn && !isLast) { if (ansInput) ansInput.disabled = true; if (submitBtn) submitBtn.style.display = 'none'; nextBtn.style.display = 'block'; }

            return {
                period: state.currentPeriod,
                topic: problem.topic,
                submitted: submitted,
                correct: correct,
                errorPct: Math.round(errorPct * 100) / 100,
                points: points,
                maxPoints: problem.maxPoints,
                grade: grade,
                cumulativeScore: ds.score
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score');
            uiManager.bind('maxScoreDisplay', 'domainState.maxPossible');
            uiManager.bind('accuracyDisplay', 'domainState.correctCount', function(v) {
                var st = window.mySimulation ? window.mySimulation.state : null;
                var total = st && st.domainState ? (st.domainState.answeredCount || 0) : 0;
                if (total <= 0) return '0%';
                return Math.round((v / total) * 100) + '%';
            });
            uiManager.bind('streakDisplay', 'domainState.streak');
            var self = this; var submitBtn = document.getElementById('nextPeriodBtn'); var nextBtn = document.getElementById('nextProblemBtn'); if (submitBtn && !nextBtn) { nextBtn = document.createElement('button'); nextBtn.id = 'nextProblemBtn'; nextBtn.className = 'btn btn-success btn-lg btn-block mt-2'; nextBtn.style.display = 'none'; var lbl = window.mySimulation ? window.mySimulation.t('next_problem_btn') : 'Next Problem'; nextBtn.textContent = (lbl === 'next_problem_btn') ? 'Next Problem' : lbl; submitBtn.parentNode.insertBefore(nextBtn, submitBtn.nextSibling); } if (nextBtn && !nextBtn._mbWired) { nextBtn._mbWired = true; nextBtn.addEventListener('click', function() { self._updateBriefing(window.mySimulation.state); nextBtn.style.display = 'none'; if (submitBtn) submitBtn.style.display = 'block'; var ansInput = document.getElementById('answerInput'); if (ansInput) { ansInput.disabled = false; ansInput.focus(); } }); }
        }

        formatCompletionMessage(summary) { var t = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; }; var s = summary || {}; var pct = (s.percentage != null) ? s.percentage : 0; var perf = s.performance || ''; var insights = (s.insights || []).map(function(i) { return `<li>${i}</li>`; }).join(''); var pts = ((s.totalPoints != null) ? s.totalPoints : 0) + ' / ' + ((s.maxPoints != null) ? s.maxPoints : 0); var exact = ((s.correctCount != null) ? s.correctCount : 0) + ' / ' + PROBLEMS.length; var rec = insights ? `<hr><div style='text-align:left'><strong>${t('complete_recommendations')}</strong><ul>${insights}</ul></div>` : ''; return `<div style='text-align:center;padding:12px'><div style='font-size:2.6rem;font-weight:800;color:#1a237e'>${pct}%</div><div style='text-transform:uppercase;letter-spacing:.5px;font-size:.8rem;color:#888;margin-bottom:12px'>${t('complete_score')}</div><div style='margin-bottom:12px'><span class='badge badge-primary' style='font-size:1rem;padding:8px 16px'>${perf}</span></div><p style='font-size:1.1rem;margin-bottom:4px'>${pts} ${t('complete_points')}</p><p style='color:#888;margin-bottom:12px'>${exact} ${t('complete_exact')}</p>${rec}</div>`; }

        getChartConfig() {
            var t = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; };
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
