                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_score_title') },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: t('col_points') } }
                        }
                    }
