                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.scoreHistory.map(function(_, i) { return 'P' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: ds.scoreHistory }]
                },
                errorChart: {
                    labels: labels,
                    datasets: [{ data: ds.errorHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || history.length === 0) return {};

            var totalPoints = 0;
            var maxPoints = 0;
            var correctCount = 0;

            history.forEach(function(h) {
                if (h.results) {
                    totalPoints += h.results.points || 0;
                    maxPoints += h.results.maxPoints || 0;
                    if (h.results.grade === 'correct') correctCount += 1;
                }
            });

            var t = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; };
            var pct = maxPoints > 0 ? (totalPoints / maxPoints) * 100 : 0;
            var performance = t('perf_needs_practice');
            if (pct >= 90) performance = t('perf_excellent');
            else if (pct >= 75) performance = t('perf_good');
            else if (pct >= 60) performance = t('perf_satisfactory');

            var insights = [];
            if (pct >= 90) {
                insights.push(t('insight_excellent'));
            } else if (pct >= 75) {
                insights.push(t('insight_good'));
            } else if (pct >= 60) {
                insights.push(t('insight_satisfactory'));
            } else {
                insights.push(t('insight_needs_practice'));
            }

            var isEs = eqLang() === 'es';
            var weakTopics = [];
            history.forEach(function(h) {
                if (h.results && h.results.errorPct > 15) {
                    var wp = PROBLEMS.filter(function(pp) { return pp.topic === h.results.topic; })[0];
                    weakTopics.push(wp ? (isEs ? wp.topicEs : wp.topic) : h.results.topic);
                }
            });
            if (weakTopics.length > 0) {
                insights.push(t('insight_topics_review').split('{topics}').join(weakTopics.join(', ')));
            }

            return {
                totalPoints: totalPoints,
                maxPoints: maxPoints,
                percentage: Math.round(pct),
                correctCount: correctCount,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.grade === 'incorrect') {
                return window.mySimulation.t('hint_review');
            }
            if (results.grade === 'partial') {
                return window.mySimulation.t('hint_close');
            }
            if (results.grade === 'correct' && state.domainState.streak >= 3) {
                return window.mySimulation.t('hint_streak');
            }
            return null;
        }

